        ('Premium', 200, 1499.00, 0.00, 'Up to 200 Mbps — for busy households with multiple devices.', 'active', 0),
        ('Professional', 300, 1999.00, 0.00, 'Up to 300 Mbps — for demanding households and small teams.', 'active', 0),
        ('Pro', 400, 2499.00, 0.00, 'Up to 400 Mbps — for power users and high-bandwidth work.', 'active', 0),
        ('Ultimate', 500, 2999.00, 0.00, 'Up to 500 Mbps — for the highest-performance connected experience.', 'active', 0)
