create table if not exists public.clients (id bigint generated by default as identity primary key, client_code varchar(50) not null unique, full_name varchar(100) not null, contact_number varchar(20), email varchar(100), branch_name varchar(100) not null default 'Balilihan', registered_barangay_name varchar(100), barangay_id bigint references public.barangays(id) on delete set null, exact_address text, wifi_plan varchar(100), internet_plan_id bigint references public.internet_plans(id) on delete set null, monthly_rate numeric(10,2) not null default 0, installation_fee numeric(10,2) not null default 0, installation_date date, status varchar(20) not null default 'active' check (status in ('active','inactive','suspended')), archived smallint not null default 0 check (archived in (0, 1)), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.clients add column if not exists branch_name varchar(100) not null default 'Balilihan', add column if not exists registered_barangay_name varchar(100);
create table if not exists public.bills (id bigint generated by default as identity primary key, client_id bigint not null references public.clients(id) on delete cascade, bill_number varchar(50) not null unique, billing_period_start date not null, billing_period_end date not null, amount numeric(10,2) not null, due_date date not null, status varchar(20) not null default 'pending' check (status in ('pending','paid','overdue','cancelled')), notes text, created_at timestamptz not null default now(), unique(client_id,billing_period_start));
create table if not exists public.payments (id bigint generated by default as identity primary key, client_id bigint not null references public.clients(id) on delete cascade, bill_id bigint references public.bills(id) on delete set null, amount numeric(10,2) not null check (amount > 0), payment_date date not null, payment_method varchar(20) not null default 'cash' check (payment_method in ('cash','gcash','bank_transfer','other')), reference_number varchar(100), notes text, received_by bigint references public.users(id) on delete set null, submission_token uuid unique, created_at timestamptz not null default now());
create table if not exists public.employees (id bigint generated by default as identity primary key, employee_code varchar(50) not null unique, user_id bigint references public.users(id) on delete set null, full_name varchar(100) not null, position varchar(50), department varchar(50), contact_number varchar(20), email varchar(100), address text, date_hired date, branch_name varchar(100) not null default 'Balilihan', daily_rate numeric(10,2) not null default 0, status varchar(20) not null default 'active', created_at timestamptz not null default now());
create table if not exists public.attendance (id bigint generated by default as identity primary key, employee_id bigint not null references public.employees(id) on delete cascade, attendance_date date not null, morning_time_in time, morning_time_out time, afternoon_time_in time, afternoon_time_out time, overtime_time_in time, overtime_time_out time, overtime_minutes integer not null default 0, status_morning varchar(20), status_afternoon varchar(20), qr_code_used varchar(100), total_hours numeric(5,2) not null default 0, notes text, branch_name varchar(100), created_at timestamptz not null default now(), unique(employee_id,attendance_date));
create table if not exists public.payroll (id bigint generated by default as identity primary key, employee_id bigint not null references public.employees(id) on delete cascade, payroll_period_start date not null, payroll_period_end date not null, total_days_worked numeric(5,2) not null default 0, total_hours numeric(8,2) not null default 0, daily_rate numeric(10,2) not null, basic_salary numeric(10,2) not null default 0, gross_pay numeric(10,2) not null default 0, deductions numeric(10,2) not null default 0, net_pay numeric(10,2) not null default 0, status varchar(20) not null default 'draft', archived smallint not null default 0 check (archived in (0, 1)), created_at timestamptz not null default now());
alter table public.payroll add column if not exists monthly_basic_salary numeric(10,2) not null default 0, add column if not exists hourly_rate numeric(10,2) not null default 0, add column if not exists overtime_hours numeric(8,2) not null default 0, add column if not exists late numeric(8,2) not null default 0, add column if not exists undertime numeric(8,2) not null default 0, add column if not exists absent numeric(8,2) not null default 0, add column if not exists overtime_pay numeric(10,2) not null default 0, add column if not exists regular_holiday numeric(10,2) not null default 0, add column if not exists special_holiday numeric(10,2) not null default 0, add column if not exists night_differential numeric(10,2) not null default 0, add column if not exists incentives numeric(10,2) not null default 0, add column if not exists allowances numeric(10,2) not null default 0, add column if not exists leave_pay numeric(10,2) not null default 0, add column if not exists rest_day_pay numeric(10,2) not null default 0, add column if not exists salary_adjustment numeric(10,2) not null default 0, add column if not exists other_earnings numeric(10,2) not null default 0, add column if not exists sss numeric(10,2) not null default 0, add column if not exists philhealth numeric(10,2) not null default 0, add column if not exists pagibig numeric(10,2) not null default 0, add column if not exists withholding_tax numeric(10,2) not null default 0, add column if not exists cash_advance numeric(10,2) not null default 0, add column if not exists salary_loan numeric(10,2) not null default 0, add column if not exists hdmf_loan numeric(10,2) not null default 0, add column if not exists other_deductions numeric(10,2) not null default 0, add column if not exists late_minutes integer not null default 0, add column if not exists undertime_minutes integer not null default 0, add column if not exists computation_mode varchar(10);
create table if not exists public.inventory (id bigint generated by default as identity primary key, item_name varchar(100) not null, sku varchar(100) not null unique, category varchar(50) not null, quantity integer not null default 0 check (quantity >= 0), unit_price numeric(10,2) not null default 0, description text, supplier varchar(100), reorder_level integer not null default 5, status varchar(20) not null default 'active', archived smallint not null default 0 check (archived in (0, 1)), created_at timestamptz not null default now(), branch_name varchar(100) not null default 'Balilihan', constraint inventory_branch_item_category_key unique(branch_name,item_name,category));
create table if not exists public.inventory_requests (id bigint generated by default as identity primary key, employee_id bigint not null references public.employees(id) on delete cascade, employee_name varchar(100) not null, inventory_id bigint references public.inventory(id) on delete set null, item_name varchar(100) not null, quantity integer not null check (quantity > 0), comments text, status varchar(20) not null default 'pending', approved_by bigint references public.users(id) on delete set null, approved_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.login_history (id bigint generated by default as identity primary key, user_id bigint references public.users(id) on delete cascade, username varchar(50) not null, full_name varchar(100), role varchar(20), ip_address varchar(45), user_agent text, login_time timestamptz not null default now(), logout_time timestamptz, status varchar(20) not null default 'success', error_message varchar(255));
create table if not exists public.system_settings (id bigint generated by default as identity primary key, setting_key varchar(100) not null unique, setting_value text, setting_label varchar(100), updated_at timestamptz not null default now());
create table if not exists public.report_history (id bigint generated by default as identity primary key, report_name varchar(100) not null, report_type varchar(20) not null, date_from date, date_to date, filters jsonb, generated_by bigint references public.users(id) on delete set null, record_count integer not null default 0, status varchar(50), generated_at timestamptz not null default now());
create table if not exists public.qr_codes (id bigint generated by default as identity primary key, qr_code varchar(255) not null unique, qr_type varchar(20) not null, valid_date date not null, valid_from time not null, valid_until time not null, status varchar(20) not null default 'active', created_by bigint references public.users(id) on delete set null, created_at timestamptz not null default now());
create table if not exists public.inventory_stock_movements (id bigint generated by default as identity primary key, inventory_id bigint not null references public.inventory(id) on delete cascade, quantity_change integer not null, balance_after integer not null, movement_type varchar(30) not null, remarks text, performed_by bigint references public.users(id) on delete set null, created_at timestamptz not null default now());
create table if not exists public.client_plan_change_histories (id bigint generated by default as identity primary key, client_id bigint not null references public.clients(id) on delete cascade, previous_internet_plan_id bigint references public.internet_plans(id) on delete set null, previous_plan_name varchar(100), previous_monthly_rate numeric(10,2) not null default 0, new_internet_plan_id bigint references public.internet_plans(id) on delete set null, new_plan_name varchar(100) not null, new_monthly_rate numeric(10,2) not null default 0, reason varchar(1000), changed_by bigint references public.users(id) on delete set null, created_at timestamptz not null default now());

-- Field work from the employee app (NAP boxes, work requests, app tokens).
CREATE TABLE IF NOT EXISTS public.nap_boxes (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name varchar(50) NOT NULL,
    branch_name varchar(100) NOT NULL,
    barangay_name varchar(100) NOT NULL,
    location varchar(255),
    total_ports smallint NOT NULL CHECK (total_ports > 0),
    status varchar(20) NOT NULL DEFAULT 'active',
    archived boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT nap_boxes_branch_name_unique UNIQUE (branch_name, name)
);
CREATE INDEX IF NOT EXISTS nap_boxes_branch_barangay_index ON public.nap_boxes (branch_name, barangay_name);

CREATE TABLE IF NOT EXISTS public.nap_ports (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nap_box_id bigint NOT NULL REFERENCES public.nap_boxes(id) ON DELETE CASCADE,
    port_number smallint NOT NULL,
    status varchar(20) NOT NULL DEFAULT 'available',
    client_id bigint REFERENCES public.clients(id) ON DELETE SET NULL,
    occupied_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT nap_ports_box_number_unique UNIQUE (nap_box_id, port_number)
);

CREATE TABLE IF NOT EXISTS public.work_requests (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    request_code varchar(30) NOT NULL UNIQUE,
    branch_name varchar(100) NOT NULL,
    employee_id bigint NOT NULL REFERENCES public.employees(id) ON DELETE CASCADE,
    work_type varchar(20) NOT NULL,
    status varchar(30) NOT NULL DEFAULT 'pending_approval',
    client_id bigint REFERENCES public.clients(id) ON DELETE SET NULL,
    new_client_name varchar(100),
    new_client_phone varchar(20),
    new_client_address text,
    barangay_name varchar(100),
    location text,
    problem_details text,
    nap_box_id bigint REFERENCES public.nap_boxes(id) ON DELETE SET NULL,
    nap_port_id bigint REFERENCES public.nap_ports(id) ON DELETE SET NULL,
    actual_nap_box_id bigint REFERENCES public.nap_boxes(id) ON DELETE SET NULL,
    actual_nap_port_id bigint REFERENCES public.nap_ports(id) ON DELETE SET NULL,
    completion_notes text,
    admin_remarks text,
    submitted_at timestamptz,
    reviewed_by bigint REFERENCES public.users(id) ON DELETE SET NULL,
    reviewed_at timestamptz,
    completed_at timestamptz,
    confirmed_by bigint REFERENCES public.users(id) ON DELETE SET NULL,
    confirmed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS work_requests_branch_status_index ON public.work_requests (branch_name, status);
CREATE INDEX IF NOT EXISTS work_requests_employee_index ON public.work_requests (employee_id);

CREATE TABLE IF NOT EXISTS public.work_request_materials (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    work_request_id bigint NOT NULL REFERENCES public.work_requests(id) ON DELETE CASCADE,
    inventory_id bigint REFERENCES public.inventory(id) ON DELETE SET NULL,
    item_name varchar(100) NOT NULL,
    used_quantity integer NOT NULL DEFAULT 0 CHECK (used_quantity >= 0),
    returned_quantity integer NOT NULL DEFAULT 0 CHECK (returned_quantity >= 0),
    damaged_quantity integer NOT NULL DEFAULT 0 CHECK (damaged_quantity >= 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.employee_api_tokens (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    employee_id bigint NOT NULL REFERENCES public.employees(id) ON DELETE CASCADE,
    login_history_id bigint,
    token_hash char(64) NOT NULL UNIQUE,
    expires_at timestamptz,
    last_used_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS employee_api_tokens_employee_index ON public.employee_api_tokens (employee_id);

ALTER TABLE public.inventory_requests
    ADD COLUMN IF NOT EXISTS request_type varchar(10) NOT NULL DEFAULT 'out',
    ADD COLUMN IF NOT EXISTS item_condition varchar(30),
    ADD COLUMN IF NOT EXISTS area_used varchar(150),
    ADD COLUMN IF NOT EXISTS person_in_charge varchar(100);

-- The photo of a NAP box (base64 text of a picture the browser has shrunk), apart from nap_boxes so the list never loads it.
CREATE TABLE IF NOT EXISTS public.nap_box_photos (
    nap_box_id bigint PRIMARY KEY REFERENCES public.nap_boxes(id) ON DELETE CASCADE,
    mime_type varchar(30) NOT NULL,
    data text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.nap_box_photos ENABLE ROW LEVEL SECURITY;

-- Inventory and NAP boxes work as one: a stock transaction says which employee, client and NAP box it was for.
ALTER TABLE public.inventory_stock_movements
    ADD COLUMN IF NOT EXISTS employee_id bigint REFERENCES public.employees(id) ON DELETE SET NULL,
    ADD COLUMN IF NOT EXISTS client_id bigint REFERENCES public.clients(id) ON DELETE SET NULL,
    ADD COLUMN IF NOT EXISTS nap_box_id bigint REFERENCES public.nap_boxes(id) ON DELETE SET NULL,
    ADD COLUMN IF NOT EXISTS work_request_id bigint REFERENCES public.work_requests(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS inventory_stock_movements_nap_box_index ON public.inventory_stock_movements (nap_box_id);

ALTER TABLE public.nap_boxes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.nap_ports ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.work_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.work_request_materials ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.employee_api_tokens ENABLE ROW LEVEL SECURITY;

alter table public.users enable row level security; alter table public.clients enable row level security; alter table public.bills enable row level security; alter table public.payments enable row level security; alter table public.employees enable row level security; alter table public.inventory enable row level security;
